/** Debounce that keeps `.cancel()` and `.flush()` available for cleanup. */
function debounce(fn, delay) {
  let timer = null
  const wrapped = (...args) => {
    if (timer !== null) clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      fn(...args)
    }, delay)
  }
  wrapped.cancel = () => {
    if (timer !== null) clearTimeout(timer)
    timer = null
  }
  wrapped.flush = (...args) => {
    if (timer !== null) clearTimeout(timer)
    timer = null
    fn(...args)
  }
  return wrapped
}

