/** Read an exported JSON payload; throws with a readable reason the UI can toast. */
function parseJsonArchive(text) {
  let parsed
  try {
    parsed = JSON.parse(String(text === undefined || text === null ? '' : text))
  } catch {
    throw new Error('file is not valid JSON')
  }
  const candidate = parsed !== null && typeof parsed === 'object' && parsed.snapshot !== null && typeof parsed.snapshot === 'object' ? parsed.snapshot : parsed
  if (candidate === null || typeof candidate !== 'object' || Array.isArray(candidate)) throw new Error('file does not contain a document tree')
  if (!Array.isArray(candidate.workspaces)) throw new Error('import needs a "workspaces" array')
  if (!Array.isArray(candidate.nodes)) throw new Error('import needs a "nodes" array')
  for (const node of candidate.nodes) {
    if (node === null || typeof node !== 'object' || typeof node.id !== 'string' || node.id === '') {
      throw new Error('every imported node needs a non-empty id')
    }
  }
  return candidate
}

/**
 * Fold an imported canvas into the local one. Imported cards are added only when
 * their document/attachment survived the merge, imported links only when both
 * cards exist, and the local layout is never moved or replaced. Merging the same
 * archive twice therefore changes nothing.
 */
function mergeCanvasData(current, incoming, nodeIds, mediaIds) {
  const base = normalizeCanvasData(current)
  const extra = normalizeCanvasData(incoming)
  const items = base.items.slice()
  const present = new Set(items.map((item) => item.id))
  for (const item of extra.items) {
    if (present.has(item.id)) continue
    if (item.kind === 'doc' ? !nodeIds.has(item.refId) : !mediaIds.has(item.refId)) continue
    present.add(item.id)
    items.push(item)
  }
  const links = base.links.slice()
  const pairs = new Set(base.links.map((link) => [link.from, link.to].sort().join('::')))
  for (const link of extra.links) {
    if (!present.has(link.from) || !present.has(link.to)) continue
    const key = [link.from, link.to].sort().join('::')
    if (pairs.has(key)) continue
    pairs.add(key)
    links.push({ id: 'link:' + key, from: link.from, to: link.to })
  }
  return { items, links }
}

/** Merge an imported snapshot into the current one: nothing is replaced or overwritten. */
function mergeSnapshot(current, incoming) {
  const base = normalizeSnapshot(current)
  const extra = normalizeSnapshot(incoming)
  const workspaceIds = new Set(base.workspaces.map((workspace) => workspace.id))
  const nodeIds = new Set(base.nodes.map((node) => node.id))
  const workspaces = base.workspaces.concat(extra.workspaces.filter((workspace) => !workspaceIds.has(workspace.id)))
  const keptWorkspaces = new Set(workspaces.map((workspace) => workspace.id))
  const incomingNodes = extra.nodes.filter((node) => !nodeIds.has(node.id) && keptWorkspaces.has(node.workspaceId))
  const keptNodes = new Set(base.nodes.map((node) => node.id).concat(incomingNodes.map((node) => node.id)))
  const nodes = base.nodes.concat(
    incomingNodes.map((node) => (node.parentId !== null && node.parentId !== undefined && !keptNodes.has(node.parentId) ? Object.assign({}, node, { parentId: null }) : node)),
  )
  const mediaIds = new Set()
  for (const node of nodes) {
    for (const item of Array.isArray(node.media) ? node.media : []) {
      if (item !== null && typeof item === 'object' && typeof item.id === 'string') mediaIds.add(item.id)
    }
  }
  const canvas = mergeCanvasData(base.canvas, extra.canvas, keptNodes, mediaIds)
  return Object.assign({}, base, { workspaces, nodes, canvas })
}

/** Observable store backed by the host route. */
function createStore() {  const listeners = new Set()
  const state = {
    snapshot: emptySnapshot(),
    revision: 0,
    updatedAt: null,
    status: 'loading',
    error: null,
    saveState: 'idle',
    saveError: null,
    // Set when the host refused a save because another session wrote first. Autosave stays
    // paused and the panel shows a banner until the user chooses Reload or Overwrite.
    conflict: null,
    // One-shot note from the host: that save carried no expectedRevision (compat path).
    saveWarning: null,
    // Bumped whenever a host snapshot replaces the local one, so the editor drops keystrokes
    // it had not flushed yet instead of replaying them onto the fresh copy.
    resetToken: 0,
    storage: null,
    // DSH projects reported by the host; the plugin never invents or deletes them.
    projects: {
      status: 'idle',
      projects: [],
      defaultProjectId: null,
      directory: null,
      source: null,
      exists: false,
      warning: null,
      error: null,
      syncedAt: null,
    },
  }

  const emit = () => {
    for (const listener of listeners) {
      try {
        listener()
      } catch (error) {
        console.error('[dsh-scriptorium] listener failed', error)
      }
    }
  }

  const replace = (snapshot) => {
    state.snapshot = snapshot
    emit()
  }

  /**
   * A save carries the revision this tab last saw. The host answers 409 with the revision it
   * is actually at, which is the only way the panel can tell "my write is stale" from
   * "the disk is broken".
   */
  const postSave = (expectedRevision) => api('/save', { method: 'POST', body: { snapshot: state.snapshot, expectedRevision } })

  const applySaved = (result) => {
    state.revision = result.revision
    state.updatedAt = result.updatedAt
    state.saveState = 'saved'
    state.saveError = null
    state.saveWarning = typeof result.warning === 'string' && result.warning !== '' ? result.warning : null
  }

  const setConflict = (error) => {
    state.conflict = {
      localRevision: state.revision,
      currentRevision: typeof error.currentRevision === 'number' ? error.currentRevision : null,
      at: nowIso(),
    }
    state.saveState = 'conflict'
    state.saveError = null
  }

  const isConflict = (error) => error !== null && typeof error === 'object' && error.code === 'conflict'

  /** One write, leaving the state describing the outcome. */
  const attemptSave = async () => {
    state.saveState = 'saving'
    state.saveError = null
    emit()
    try {
      applySaved(await postSave(state.revision))
      emit()
    } catch (error) {
      if (isConflict(error)) {
        setConflict(error)
        emit()
        return
      }
      state.saveState = 'error'
      state.saveError = (error && error.message) || String(error)
      emit()
    }
  }

  let inFlight = null
  let queued = false

  /**
   * Save now. An unresolved conflict pauses writing until the banner decides, and a save that
   * arrives while another one is in flight is coalesced into one follow-up instead of racing
   * it: two requests would carry the same expectedRevision and burn the second as a conflict.
   */
  const saveNow = () => {
    if (state.status === 'loading' || state.conflict !== null) return Promise.resolve()
    if (inFlight !== null) {
      queued = true
      return inFlight
    }
    inFlight = (async () => {
      try {
        do {
          queued = false
          await attemptSave()
        } while (queued && state.conflict === null && state.saveState !== 'error')
      } finally {
        inFlight = null
      }
    })()
    return inFlight
  }

  const scheduleSave = debounce(saveNow, SAVE_DEBOUNCE_MS)

  /**
   * Banner "Reload": take the host copy and drop this tab's unsaved edits, then resume.
   * The bumped resetToken makes the editor drop keystrokes it had not flushed yet, which
   * would otherwise land on the fresh snapshot on the next blur.
   */
  const reload = async () => {
    if (state.conflict === null) return false
    try {
      const result = await api('/state')
      state.revision = Number.isInteger(result.revision) ? result.revision : 0
      state.updatedAt = result.updatedAt || null
      if (result.snapshot !== null && typeof result.snapshot === 'object') state.snapshot = normalizeSnapshot(result.snapshot)
      state.conflict = null
      state.saveError = null
      state.saveWarning = null
      state.saveState = 'saved'
      state.resetToken += 1
      emit()
      return true
    } catch (error) {
      state.saveState = 'error'
      state.saveError = (error && error.message) || String(error)
      emit()
      return false
    }
  }

  /**
   * Banner "Overwrite": replace the host copy with this tab's snapshot. Exactly one retry,
   * against the revision the 409 named; a second conflict re-arms the banner instead of
   * looping, so a busy host can never turn this into a write storm.
   */
  const overwrite = async () => {
    if (state.conflict === null) return 'idle'
    const target = state.conflict.currentRevision
    state.saveState = 'saving'
    state.saveError = null
    emit()
    try {
      applySaved(await postSave(typeof target === 'number' ? target : state.revision))
      state.conflict = null
      emit()
      return 'saved'
    } catch (error) {
      if (isConflict(error)) {
        setConflict(error)
        emit()
        return 'conflict'
      }
      state.saveState = 'error'
      state.saveError = (error && error.message) || String(error)
      emit()
      return 'error'
    }
  }

  /** Drop the one-shot compatibility note once the UI has shown it. */
  const clearWarning = () => {
    if (state.saveWarning === null) return
    state.saveWarning = null
    emit()
  }

  /** Mutate a clone of the snapshot, then persist on the debounce (or immediately). */
  const commit = (mutator, options = {}) => {
    const draft = deepClone(state.snapshot)
    mutator(draft)
    state.snapshot = draft
    emit()
    if (options.immediate === true) {
      scheduleSave.cancel()
      void saveNow()
    } else if (draft.settings.autoSave !== false && state.conflict === null) {
      // Autosave stays paused while a conflict is open: the banner owns the next write.
      scheduleSave()
    }
    return draft
  }

  /** Read the Harness project list; the host owns it, this store only mirrors it. */
  const syncProjects = async () => {
    state.projects = Object.assign({}, state.projects, { status: 'loading', error: null })
    emit()
    try {
      const result = await api('/projects')
      const projects = result !== null && typeof result === 'object' && Array.isArray(result.projects) ? result.projects : []
      state.projects = {
        status: 'ready',
        projects,
        defaultProjectId: (result && result.defaultProjectId) || null,
        directory: (result && result.directory) || null,
        source: (result && result.source) || null,
        exists: Boolean(result && result.exists),
        warning: (result && result.warning) || null,
        error: null,
        syncedAt: nowIso(),
      }
      emit()
      return state.projects
    } catch (error) {
      state.projects = Object.assign({}, state.projects, { status: 'error', error: (error && error.message) || String(error) })
      emit()
      throw error
    }
  }

  const load = async () => {
    state.status = 'loading'
    state.error = null
    emit()
    try {
      const [result, health] = await Promise.all([api('/state'), api('/health')])
      state.storage = health
      state.revision = result.revision || 0
      state.updatedAt = result.updatedAt || null
      state.conflict = null
      state.resetToken += 1
      if (result.snapshot === null || typeof result.snapshot !== 'object') {
        state.snapshot = seedSnapshot()
        state.status = 'ready'
        emit()
        await saveNow()
      } else {
        state.snapshot = normalizeSnapshot(result.snapshot)
        state.status = 'ready'
        emit()
      }
    } catch (error) {
      state.status = 'error'
      state.error = (error && error.message) || String(error)
      emit()
    }
  }

  return {
    state,
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    load,
    syncProjects,
    commit,
    saveNow,
    reload,
    overwrite,
    clearWarning,
    replace,
    dispose() {
      scheduleSave.cancel()
      listeners.clear()
    },
  }
}

