/** Read a File as base64 (attachment upload) or as raw bytes (ZIP import). */
function readFileBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      const result = String(reader.result || '')
      const comma = result.indexOf(',')
      resolve(comma >= 0 ? result.slice(comma + 1) : result)
    }
    reader.onerror = () => reject((reader.error && reader.error.message) || 'could not read file')
    reader.readAsDataURL(file)
  })
}

function readFileBytes(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(new Uint8Array(reader.result || new ArrayBuffer(0)))
    reader.onerror = () => reject((reader.error && reader.error.message) || 'could not read file')
    reader.readAsArrayBuffer(file)
  })
}

/** Save a Blob/bytes through a temporary object URL. */
function downloadBlob(filename, blob) {
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.rel = 'noopener'
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  setTimeout(() => URL.revokeObjectURL(url), 4000)
}

function pickFile(accept) {
  return new Promise((resolve) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = accept
    input.onchange = () => {
      const file = input.files && input.files[0]
      resolve(file || null)
    }
    input.click()
  })
}

function App({ store }) {
  const [tick, setTick] = React.useState(0)
  const [view, setView] = React.useState('doc')
  const [searchOpen, setSearchOpen] = React.useState(false)
  const [paletteOpen, setPaletteOpen] = React.useState(false)
  const [settingsOpen, setSettingsOpen] = React.useState(false)
  const [toasts, setToasts] = React.useState([])
  const [tagFilter, setTagFilter] = React.useState(null)
  const [query, setQuery] = React.useState('')
  const [previewMedia, setPreviewMedia] = React.useState(null)
  const [busy, setBusy] = React.useState(null)
  // Whether the user hid the conflict banner; a fresh conflict clears it again.
  const [conflictHidden, setConflictHidden] = React.useState(false)
  const bootedRef = React.useRef(false)
  const projectSyncedRef = React.useRef(false)

  React.useEffect(() => {
    const unsubscribe = store.subscribe(() => setTick((value) => value + 1))
    if (!bootedRef.current) {
      bootedRef.current = true
      if (store.state.status !== 'ready') void store.load()
    }
    return unsubscribe
  }, [])

  const snapshot = store.state.snapshot
  const ui = snapshot.ui || {}
  const settings = snapshot.settings || {}
  const activeNode = ui.activeNodeId ? model.nodeById(snapshot, ui.activeNodeId) : null
  const activeWorkspace = ui.activeWorkspaceId ? model.workspaceById(snapshot, ui.activeWorkspaceId) : null
  const projectState = store.state.projects || { status: 'idle', projects: [] }
  const projectList = Array.isArray(projectState.projects) ? projectState.projects : []
  // Project mode kicks in as soon as the host reports projects, or when the stored
  // snapshot already has bound notebooks (so the UI does not flip while loading).
  const projectMode = projectList.length > 0 || snapshot.workspaces.some((workspace) => model.isProjectWorkspace(workspace) || workspace.projectMissing === true)
  const projectLoading = projectState.status === 'loading'

  const notify = React.useCallback((message, kind) => {
    const id = uid('toast')
    setToasts((current) => current.concat([{ id, message, kind: kind || 'info' }]))
    window.setTimeout(() => {
      setToasts((current) => current.filter((toast) => toast.id !== id))
    }, 2800)
  }, [])

  const commit = (mutator, options) => store.commit(mutator, options)

  const conflict = store.state.conflict || null
  const conflictStamp = conflict === null ? '' : String(conflict.at) + '|' + String(conflict.currentRevision)

  // A new conflict always reopens the banner, even when the previous one was dismissed.
  React.useEffect(() => {
    setConflictHidden(false)
  }, [conflictStamp])

  // The host flags a save that carried no expectedRevision (compat path); surface it once.
  const saveWarning = store.state.saveWarning || null
  React.useEffect(() => {
    if (saveWarning === null) return
    notify(saveWarning, 'info')
    if (typeof store.clearWarning === 'function') store.clearWarning()
  }, [saveWarning])

  const resolveConflict = (kind) => {
    const run = store[kind]
    if (typeof run !== 'function') return
    run().then((outcome) => {
      if (outcome === 'conflict') notify('The host changed again; resolve the new conflict.', 'error')
      else if (outcome === false) notify('Could not reload the host copy.', 'error')
    })
  }

  const actions = {
    view,
    notify,
    setTagFilter,
    selectTag: (tag) => {
      if (tagFilter === tag) {
        setTagFilter(null)
        setView('doc')
        return
      }
      setTagFilter(tag)
      setView('tag')
    },
    openView: (name) => {
      if (name === 'favorites' || name === 'trash') setView(name)
      else if (VIEWS.some((entry) => entry.id === name)) setView(name)
      else setView('doc')
    },
    openNode: (id) => {
      setView('doc')
      commit((draft) => model.patchUi(draft, { activeNodeId: id }))
    },
    toggleExpanded: (id) => commit((draft) => model.toggleExpanded(draft, id)),
    selectWorkspace: (id) => commit((draft) => model.patchUi(draft, { activeWorkspaceId: id, activeNodeId: null })),
    createWorkspace: (name) => commit((draft) => model.createWorkspace(draft, name), { immediate: true }),
    renameWorkspace: (id, name) => commit((draft) => model.renameWorkspace(draft, id, name)),
    removeWorkspace: (id) => {
      commit((draft) => model.removeWorkspace(draft, id), { immediate: true })
      notify('Workspace deleted', 'info')
    },
    syncProjects: async (options = {}) => {
      try {
        const result = await store.syncProjects()
        if (result.projects.length === 0) {
          if (options.silent !== true) notify('No DSH projects found — create one in the Harness first', 'info')
          return null
        }
        let summary = null
        commit((draft) => {
          summary = model.syncProjects(draft, result.projects, result.defaultProjectId)
        }, { immediate: true })
        if (options.silent !== true && summary !== null) {
          const parts = []
          if (summary.created > 0) parts.push(summary.created + ' created')
          if (summary.linked > 0) parts.push(summary.linked + ' linked')
          if (summary.updated > 0) parts.push(summary.updated + ' updated')
          if (summary.missing > 0) parts.push(summary.missing + ' missing')
          notify(parts.length === 0 ? 'Project notebooks are up to date' : 'Projects: ' + parts.join(', '), 'success')
        }
        return summary
      } catch (error) {
        if (options.silent !== true) notify('Project sync failed: ' + ((error && error.message) || String(error)), 'error')
        return null
      }
    },
    bindWorkspace: (workspaceId, projectId) => {
      const project = projectList.find((entry) => entry.id === projectId)
      if (project === undefined) return
      let result = null
      commit((draft) => {
        result = model.bindWorkspaceToProject(draft, workspaceId, project)
      }, { immediate: true })
      if (result === null) return
      if (result.merged === true) notify('Linked to ' + project.title + ' — merged ' + result.moved + ' document(s)', 'success')
      else notify('Linked to ' + project.title, 'success')
    },
    createDoc: (parentId) => {
      if (!ui.activeWorkspaceId) {
        notify('Create a workspace first', 'error')
        return
      }
      setView('doc')
      commit(
        (draft) => {
          const node = model.createNode(draft, {
            workspaceId: draft.ui.activeWorkspaceId,
            parentId: parentId || null,
            kind: 'doc',
            title: 'Untitled',
            content: '# Untitled\n\n',
          })
          model.patchUi(draft, { activeNodeId: node.id })
        },
        { immediate: true },
      )
    },
    createFolder: (parentId) => {
      if (!ui.activeWorkspaceId) {
        notify('Create a workspace first', 'error')
        return
      }
      commit((draft) => model.createNode(draft, { workspaceId: draft.ui.activeWorkspaceId, parentId: parentId || null, kind: 'folder', title: 'New folder' }), { immediate: true })
    },
    renameNode: (id, title) => commit((draft) => model.renameNode(draft, id, title)),
    setContent: (id, content) => commit((draft) => model.setContent(draft, id, content)),
    setStatus: (id, status) => commit((draft) => model.setStatus(draft, id, status)),
    toggleFavorite: (id) => commit((draft) => model.toggleFavorite(draft, id)),
    trashNode: (id) => {
      commit((draft) => model.trashNode(draft, id), { immediate: true })
      notify('Moved to trash', 'info')
    },
    restoreNode: (id) => {
      commit((draft) => model.restoreNode(draft, id), { immediate: true })
      notify('Restored', 'success')
    },
    purgeNode: (id) => {
      commit((draft) => model.purgeNode(draft, id), { immediate: true })
      notify('Deleted forever', 'info')
    },
    moveNode: (id, parentId, workspaceId) => {
      let moved = false
      commit(
        (draft) => {
          moved = model.moveNode(draft, id, parentId, workspaceId)
          if (moved) model.patchUi(draft, { expanded: (draft.ui.expanded || []).indexOf(parentId) >= 0 ? draft.ui.expanded : (draft.ui.expanded || []).concat([parentId]) })
        },
        { immediate: true },
      )
      if (!moved) notify('Cannot move a folder into itself', 'error')
    },
    addTag: (id, tag) => commit((draft) => model.addTag(draft, id, tag)),
    removeTag: (id, tag) => commit((draft) => model.removeTag(draft, id, tag)),
    patchSettings: (patch) => commit((draft) => model.patchSettings(draft, patch)),
    patchUi: (patch) => commit((draft) => model.patchUi(draft, patch)),
    openSettings: () => setSettingsOpen(true),
    saveNow: () => store.saveNow(),
    reload: () => void store.load(),
    emptyTrash: () => commit((draft) => { draft.nodes = draft.nodes.filter((node) => node.trashed !== true) }, { immediate: true }),
    exportDocument: (id) => {
      const node = model.nodeById(snapshot, id)
      if (node === null) return
      downloadText(slugify(node.title) + '.md', node.content || '', 'text/markdown')
      notify('Document exported', 'success')
    },
    exportArchive: () => {
      downloadText('scriptorium-archive-' + new Date().toISOString().slice(0, 10) + '.json', JSON.stringify(snapshot, null, 2))
      notify('JSON archive exported', 'success')
    },
    exportZip: async () => {
      setBusy('export')
      try {
        const response = await fetch(ROUTE_BASE + '/archive/export')
        if (!response.ok) {
          const detail = await response.text()
          throw new Error(detail === '' ? 'HTTP ' + response.status : detail)
        }
        downloadBlob('scriptorium-' + new Date().toISOString().slice(0, 10) + '.zip', await response.blob())
        notify('ZIP exported: notes, media and metadata', 'success')
      } catch (error) {
        notify('Export failed: ' + ((error && error.message) || String(error)), 'error')
      } finally {
        setBusy(null)
      }
    },
    importArchive: async () => {
      const file = await pickFile('.json,application/json')
      if (file === null) return
      try {
        const parsed = parseJsonArchive(await file.text())
        let merged = null
        commit((draft) => {
          merged = mergeSnapshot(draft, parsed)
          draft.workspaces = merged.workspaces
          draft.nodes = merged.nodes
          draft.canvas = merged.canvas
        }, { immediate: true })
        notify('Merged ' + parsed.nodes.length + ' item(s) from JSON', 'success')
      } catch (error) {
        notify('Import failed: ' + ((error && error.message) || String(error)), 'error')
      }
    },
    importZip: async () => {
      const file = await pickFile('.zip,application/zip')
      if (file === null) return
      setBusy('import')
      try {
        const bytes = await readFileBytes(file)
        const result = await apiRaw('/archive/import', { method: 'POST', body: bytes, contentType: 'application/zip' })
        commit((draft) => {
          const merged = mergeSnapshot(draft, result.snapshot)
          draft.workspaces = merged.workspaces
          draft.nodes = merged.nodes
          draft.canvas = merged.canvas
        }, { immediate: true })
        const counts = result.notes + ' document(s)' + (result.media.length > 0 ? ' and ' + result.media.length + ' attachment(s)' : '')
        notify('Imported ' + counts, 'success')
      } catch (error) {
        notify('ZIP import failed: ' + ((error && error.message) || String(error)), 'error')
      } finally {
        setBusy(null)
      }
    },
    uploadMedia: async (nodeId, files) => {
      if (!files || files.length === 0) return
      setBusy('media')
      try {
        for (const file of Array.from(files)) {
          const dataBase64 = await readFileBase64(file)
          const entry = await api('/media', { method: 'POST', body: { name: file.name, mime: file.type, dataBase64 } })
          commit((draft) => {
            model.addMedia(draft, nodeId, entry)
            const node = model.nodeById(draft, nodeId)
            const attached = node === null ? null : model.mediaOf(node).find((item) => item.id === entry.id) || null
            // New attachments land on the media canvas beside the document that owns them.
            if (attached !== null) canvasSyncMedia(draft, [{ media: attached, node }])
          }, { immediate: true })
        }
        notify(files.length === 1 ? 'Attachment added' : files.length + ' attachments added', 'success')
      } catch (error) {
        notify('Upload failed: ' + ((error && error.message) || String(error)), 'error')
      } finally {
        setBusy(null)
      }
    },
    removeMedia: async (nodeId, mediaId) => {
      commit((draft) => model.removeMedia(draft, nodeId, mediaId), { immediate: true })
      try {
        await apiRaw('/media/' + encodeURIComponent(mediaId), { method: 'DELETE' })
        notify('Attachment removed', 'info')
      } catch {
        notify('Attachment unlinked (the file stays on disk)', 'info')
      }
    },
    openPreview: (media) => setPreviewMedia(media),
    closePreview: () => setPreviewMedia(null),
    connectNodes: (sourceId, targetId) => {
      const source = model.nodeById(snapshot, sourceId)
      const target = model.nodeById(snapshot, targetId)
      if (source === null || target === null || sourceId === targetId) return
      const link = '[[' + target.title + ']]'
      const content = typeof source.content === 'string' ? source.content : ''
      if (content.indexOf(link) >= 0) {
        notify('Those documents are already linked', 'info')
        return
      }
      const body = content.replace(/\s*$/, '')
      const next = body === '' ? link + '\n' : body + '\n\n' + link + '\n'
      commit((draft) => model.setContent(draft, sourceId, next))
      notify('Linked to ' + target.title, 'success')
    },
    busy,
  }

  // Mirror the Harness project list once the notebook is ready. Silent on boot:
  // infrastructure work should not greet the user with a toast.
  React.useEffect(() => {
    if (store.state.status === 'loading') {
      projectSyncedRef.current = false
      return
    }
    if (store.state.status !== 'ready' || projectSyncedRef.current) return
    projectSyncedRef.current = true
    void actions.syncProjects({ silent: true })
  }, [store.state.status])

  const commands = React.useMemo(() => {
    const list = [
      { id: 'new-doc', title: 'New document', hint: 'Ctrl+N', group: 'Create', icon: 'plus', run: () => actions.createDoc(null) },
      { id: 'new-folder', title: 'New folder', group: 'Create', icon: 'folder', run: () => actions.createFolder(null) },
      ...(projectMode
        ? [{ id: 'sync-projects', title: 'Sync project notebooks', group: 'Projects', icon: 'refresh', run: () => actions.syncProjects() }]
        : [{ id: 'new-workspace', title: 'New workspace', group: 'Create', icon: 'book', run: () => actions.createWorkspace('New workspace') }]),
      { id: 'view-doc', title: 'Go to documents', group: 'Navigate', icon: 'doc', run: () => setView('doc') },
      { id: 'view-board', title: 'Go to board', group: 'Navigate', icon: 'board', run: () => setView('board') },
      { id: 'view-media', title: 'Go to media sandbox', group: 'Navigate', icon: 'image', run: () => setView('media') },
      { id: 'view-canvas', title: 'Go to media canvas', group: 'Navigate', icon: 'canvas', run: () => setView('canvas') },
      { id: 'view-graph', title: 'Go to mind graph', group: 'Navigate', icon: 'graph', run: () => setView('graph') },
      { id: 'view-favorites', title: 'Go to favourites', group: 'Navigate', icon: 'star', run: () => setView('favorites') },
      { id: 'view-trash', title: 'Go to trash', group: 'Navigate', icon: 'trash', run: () => setView('trash') },
      { id: 'search', title: 'Search documents', hint: 'Ctrl+K', group: 'Navigate', icon: 'search', run: () => setSearchOpen(true) },
      { id: 'save', title: 'Save now', hint: 'Ctrl+S', group: 'Data', icon: 'save', run: () => actions.saveNow() },
      { id: 'export', title: 'Export JSON archive', group: 'Data', icon: 'download', run: () => actions.exportArchive() },
      { id: 'export-zip', title: 'Export ZIP with media', group: 'Data', icon: 'archive', run: () => actions.exportZip() },
      { id: 'import', title: 'Import JSON archive', group: 'Data', icon: 'upload', run: () => actions.importArchive() },
      { id: 'import-zip', title: 'Import ZIP archive', group: 'Data', icon: 'upload', run: () => actions.importZip() },
      { id: 'settings', title: 'Open settings', group: 'Data', icon: 'settings', run: () => setSettingsOpen(true) },
    ]
    const docs = model.aliveNodes(snapshot).filter((node) => node.kind === 'doc' && node.workspaceId === ui.activeWorkspaceId)
    for (const node of docs.slice(0, 40)) {
      list.push({ id: 'doc-' + node.id, title: node.title, hint: 'Document', group: 'Documents', icon: node.icon || 'doc', run: () => actions.openNode(node.id) })
    }
    return list
  }, [snapshot, ui.activeWorkspaceId, view])

  React.useEffect(() => {
    const onKeyDown = (event) => {
      const meta = event.ctrlKey || event.metaKey
      const target = event.target
      const typing = target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')
      if (meta && event.key.toLowerCase() === 'k') {
        event.preventDefault()
        setPaletteOpen((open) => !open)
        return
      }
      if (event.key === 'Escape') {
        if (settingsOpen) setSettingsOpen(false)
        else if (paletteOpen) setPaletteOpen(false)
        else if (searchOpen) setSearchOpen(false)
        else if (previewMedia !== null) setPreviewMedia(null)
        else if (view === 'tag') {
          setTagFilter(null)
          setView('doc')
        } else if (conflict !== null) setConflictHidden(true)
        return
      }
      // Everything else stays out of the way while the caret is inside a field: the editor
      // owns Ctrl+S and Ctrl+B/I there, and Ctrl+N while typing in a title would be a surprise.
      if (typing) return
      if (meta && event.key.toLowerCase() === 's') {
        event.preventDefault()
        actions.saveNow()
        return
      }
      if (meta && event.key.toLowerCase() === 'n') {
        event.preventDefault()
        actions.createDoc(null)
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  })

  const favorites = model.aliveNodes(snapshot).filter((node) => node.favorite === true && node.kind === 'doc')
  const trashed = model.trashedNodes(snapshot)
  const tags = model.collectTags(snapshot)
  const filteredFavorites = tagFilter === null ? favorites : favorites.filter((node) => Array.isArray(node.tags) && node.tags.indexOf(tagFilter) >= 0)

  const renderMain = () => {
    if (store.state.status === 'loading') {
      return h('div', { className: 'dsh-scr-skeleton' }, [0, 1, 2, 3].map((index) => h('div', { key: index, className: 'dsh-scr-skeleton-line' })))
    }
    if (store.state.status === 'error') {
      return h(EmptyState, {
        icon: 'warning',
        title: 'Could not load your knowledge base',
        hint: store.state.error || 'The host store did not respond.',
        action: h('button', { type: 'button', className: 'dsh-scr-btn is-primary', onClick: () => store.load() }, 'Retry'),
      })
    }
    if (snapshot.workspaces.length === 0) {
      if (projectMode) {
        return h(EmptyState, {
          icon: 'book',
          title: 'No project notebooks yet',
          hint: projectState.error
            ? 'Project sync failed: ' + projectState.error
            : 'Notebooks mirror the projects in your Harness workspace list. Create a project there, then sync.',
          action: h(
            'button',
            { type: 'button', className: 'dsh-scr-btn is-primary', disabled: projectLoading, onClick: () => actions.syncProjects() },
            h(Icon, { name: 'refresh', size: 14 }),
            projectLoading ? 'Syncing…' : 'Sync projects',
          ),
        })
      }
      return h(EmptyState, {
        icon: 'book',
        title: 'Create your first workspace',
        hint: 'Workspaces group documents, folders and boards. Everything is stored locally in your DSH home.',
        action: h('button', { type: 'button', className: 'dsh-scr-btn is-primary', onClick: () => actions.createWorkspace('My knowledge base') }, h(Icon, { name: 'plus', size: 14 }), 'New workspace'),
      })
    }
    if (view === 'tag') {
      const tagged =
        tagFilter === null
          ? []
          : model.aliveNodes(snapshot).filter(
              (node) => node.kind === 'doc' && (!ui.activeWorkspaceId || node.workspaceId === ui.activeWorkspaceId) && Array.isArray(node.tags) && node.tags.indexOf(tagFilter) >= 0,
            )
      return h(
        'div',
        { className: 'dsh-scr-view' },
        h(
          'div',
          { className: 'dsh-scr-doc-head' },
          h('div', { className: 'dsh-scr-doc-title', style: { fontSize: 20 } }, tagFilter === null ? 'Tag' : '#' + tagFilter),
          h(
            'div',
            { className: 'dsh-scr-doc-meta' },
            h('span', null, tagged.length + ' tagged document(s)'),
            h('span', { className: 'dsh-scr-doc-meta-sep' }, 'Â·'),
            h('button', { type: 'button', className: 'dsh-scr-btn', onClick: () => actions.selectTag(tagFilter) }, 'Clear filter'),
          ),
        ),
        h(DocumentList, {
          nodes: tagged,
          snapshot,
          actions,
          onOpen: actions.openNode,
          emptyHint: 'No document carries this tag yet. Open a document and add it from the tag row.',
        }),
      )
    }
    if (view === 'media') {
      return h('div', { className: 'dsh-scr-view' }, h(MediaLibrary, { snapshot, actions, onPreview: actions.openPreview }))
    }
    if (view === 'board') {
      return h(KanbanBoard, {
        store,
        snapshot,
        workspaceId: ui.activeWorkspaceId || undefined,
        onOpen: (id) => {
          actions.openNode(id)
          setView('doc')
        },
      })
    }
    if (view === 'canvas') {
      return h('div', { className: 'dsh-scr-view dsh-scr-view-fill' }, h(MediaCanvas, {
        store,
        snapshot,
        workspaceId: ui.activeWorkspaceId || undefined,
        onOpen: actions.openNode,
        onPreview: actions.openPreview,
        notify,
      }))
    }
    if (view === 'graph') {
      return h('div', { className: 'dsh-scr-view dsh-scr-view-fill' }, h(MindGraph, {
        store,
        snapshot,
        workspaceId: ui.activeWorkspaceId || undefined,
        onOpen: actions.openNode,
        onConnect: actions.connectNodes,
        notify,
      }))
    }
    if (view === 'favorites') {
      return h(
        'div',
        { className: 'dsh-scr-view' },
        h(
          'div',
          { className: 'dsh-scr-doc-head' },
          h('div', { className: 'dsh-scr-doc-title', style: { fontSize: 20 } }, 'Favourites'),
          h(
            'div',
            { className: 'dsh-scr-doc-meta' },
            h('span', null, filteredFavorites.length + ' starred document(s)'),
            tagFilter === null ? null : h('span', { className: 'dsh-scr-chip is-active' }, '#' + tagFilter),
          ),
        ),
        h(DocumentList, { nodes: filteredFavorites, snapshot, actions, onOpen: actions.openNode, emptyHint: 'Star a document with the star icon to pin it here.' }),
      )
    }
    if (view === 'trash') {
      return h(
        'div',
        { className: 'dsh-scr-view' },
        h(
          'div',
          { className: 'dsh-scr-doc-head' },
          h('div', { className: 'dsh-scr-doc-title', style: { fontSize: 20 } }, 'Trash'),
          h(
            'div',
            { className: 'dsh-scr-doc-meta' },
            h('span', null, trashed.length + ' document(s)'),
            h('span', { className: 'dsh-scr-spacer', style: { flex: '1 1 auto' } }),
            h('button', { type: 'button', className: 'dsh-scr-btn is-danger', disabled: trashed.length === 0, onClick: () => { actions.emptyTrash(); notify('Trash emptied', 'success') } }, h(Icon, { name: 'trash', size: 14 }), 'Empty trash'),
          ),
        ),
        h(DocumentList, { nodes: trashed, snapshot, actions, onOpen: actions.openNode, showRestore: true, emptyHint: 'Deleted documents stay here until you empty the trash.' }),
      )
    }
    if (!ui.activeWorkspaceId) {
      return h(EmptyState, {
        icon: 'book',
        title: 'No project selected',
        hint: projectMode ? 'Pick a project in the sidebar, or press sync to mirror the Harness workspace list.' : 'Pick a workspace in the sidebar, or create a new one.',
      })
    }
    if (activeNode === null) {
      return h(EmptyState, {
        icon: 'doc',
        title: 'Select a document',
        hint: 'Choose a note from the sidebar, or create a new document to start writing.',
        action: h('button', { type: 'button', className: 'dsh-scr-btn is-primary', onClick: () => actions.createDoc(null) }, h(Icon, { name: 'plus', size: 14 }), 'New document'),
      })
    }
    if (activeNode.kind === 'folder') return h(FolderView, { snapshot, node: activeNode, actions })
    if (activeNode.trashed === true) {
      return h(EmptyState, {
        icon: 'trash',
        title: 'This document is in the trash',
        hint: 'Restore it to keep editing, or delete it permanently.',
        action: h('button', { type: 'button', className: 'dsh-scr-btn is-primary', onClick: () => actions.restoreNode(activeNode.id) }, h(Icon, { name: 'restore', size: 14 }), 'Restore'),
      })
    }
    return h(DocumentEditor, { store, snapshot, node: activeNode, ui, actions })
  }

  return h(
    'div',
    { className: 'dsh-scr-root' },
    h(
      'header',
      { className: 'dsh-scr-header' },
      h(
        'div',
        { className: 'dsh-scr-brand' },
        h('span', { className: 'dsh-scr-brand-mark' }, h(Icon, { name: 'book', size: 15 })),
        h('span', { className: 'dsh-scr-brand-name' }, 'Scriptorium'),
      ),
      h(IconButton, { icon: 'sidebar', label: 'Toggle sidebar', onClick: () => actions.patchUi({ sidebarCollapsed: !ui.sidebarCollapsed }) }),
      h(
        'div',
        { className: 'dsh-scr-crumbs' },
        activeWorkspace
          ? h(
              'span',
              { className: 'dsh-scr-crumb', title: activeWorkspace.path || activeWorkspace.name },
              activeWorkspace.projectMissing === true ? h('span', { className: 'dsh-scr-ws-chip' }, 'missing') : null,
              activeWorkspace.name,
            )
          : null,
        activeNode && activeWorkspace && activeNode.kind === 'doc' ? h('span', { className: 'dsh-scr-crumb-sep' }, '/') : null,
        activeNode && activeNode.kind === 'doc' ? h('span', { className: 'dsh-scr-crumb' }, activeNode.title) : null,
      ),
      h(
        'button',
        { type: 'button', className: 'dsh-scr-searchbtn', onClick: () => setSearchOpen(true) },
        h(Icon, { name: 'search', size: 13 }),
        h('span', { style: { flex: '1 1 auto' } }, 'Search documentsâ€¦'),
        h('span', { className: 'dsh-scr-kbd' }, 'Ctrl K'),
      ),
      h(
        'div',
        { className: 'dsh-scr-seg' },
        VIEWS.map((entry) =>
          h(
            'button',
            {
              key: entry.id,
              type: 'button',
              className: cx('dsh-scr-seg-btn', view === entry.id && 'is-active'),
              onClick: () => setView(entry.id),
            },
            h(Icon, { name: entry.icon, size: 12 }),
            entry.label,
          ),
        ),
      ),
      h(IconButton, { icon: 'plus', label: 'New document (Ctrl+N)', onClick: () => actions.createDoc(null) }),
      h(IconButton, { icon: 'command', label: 'Command palette (Ctrl+K)', onClick: () => setPaletteOpen(true) }),
      h(IconButton, { icon: 'settings', label: 'Settings', onClick: () => setSettingsOpen(true) }),
    ),
    conflict === null || conflictHidden
      ? null
      : h(
          'div',
          { className: 'dsh-scr-conflict', role: 'alert', 'data-current-revision': String(conflict.currentRevision) },
          h(Icon, { name: 'warning', size: 15 }),
          h(
            'div',
            { className: 'dsh-scr-conflict-text' },
            h('strong', null, 'This knowledge base changed on the host'),
            h(
              'span',
              null,
              conflict.currentRevision === null
                ? 'Another session saved after this tab loaded revision ' + conflict.localRevision + '.'
                : 'Another session saved revision ' + conflict.currentRevision + ' after this tab loaded revision ' + conflict.localRevision + '.',
            ),
            h('span', null, 'Autosave is paused. Reload takes the host copy and drops the local edits; Overwrite replaces the host copy with them.'),
          ),
          h('span', { className: 'dsh-scr-spacer' }),
          h('button', { type: 'button', className: 'dsh-scr-btn', onClick: () => resolveConflict('reload') }, h(Icon, { name: 'restore', size: 13 }), 'Reload'),
          h('button', { type: 'button', className: 'dsh-scr-btn is-primary', onClick: () => resolveConflict('overwrite') }, 'Overwrite'),
          h(IconButton, { icon: 'close', label: 'Hide this banner (Esc)', onClick: () => setConflictHidden(true) }),
        ),
    conflict !== null && conflictHidden
      ? h(
          'div',
          { className: 'dsh-scr-conflict-pill' },
          h(Icon, { name: 'warning', size: 12 }),
          h('span', null, 'Unresolved save conflict'),
          h('button', { type: 'button', className: 'dsh-scr-btn is-ghost', onClick: () => setConflictHidden(false) }, 'Resolve'),
        )
      : null,
    h(
      'div',
      { className: 'dsh-scr-body', 'data-tick': tick },
      h(Sidebar, {
        snapshot,
        ui,
        actions,
        tags,
        activeTag: tagFilter,
        projects: projectList,
        projectMode,
        projectLoading,
        onSync: () => actions.syncProjects(),
        onBind: actions.bindWorkspace,
      }),
      h('main', { className: 'dsh-scr-main' }, h('div', { className: 'dsh-scr-main-scroll' }, renderMain())),
    ),

    searchOpen
      ? h(
          'div',
          {
            className: 'dsh-scr-backdrop',
            onMouseDown: (event) => {
              if (event.target === event.currentTarget) setSearchOpen(false)
            },
          },
          h(SearchOverlay, {
            snapshot,
            query,
            workspaceId: null,
            onQueryChange: setQuery,
            onClose: () => setSearchOpen(false),
            onPick: (node) => {
              setSearchOpen(false)
              actions.openNode(node.id)
            },
          }),
        )
      : null,
    paletteOpen ? h(CommandPalette, { commands, onClose: () => setPaletteOpen(false) }) : null,
    previewMedia === null ? null : h(MediaPreview, { media: previewMedia, onClose: actions.closePreview }),
    settingsOpen ? h(SettingsModal, { snapshot, store, actions, onClose: () => setSettingsOpen(false) }) : null,

    h(
      'div',
      { className: 'dsh-scr-toast-stack' },
      toasts.map((toast) =>
        h(
          'div',
          { key: toast.id, className: cx('dsh-scr-toast', toast.kind === 'error' && 'is-error', toast.kind === 'success' && 'is-success') },
          h(Icon, { name: toast.kind === 'error' ? 'warning' : toast.kind === 'success' ? 'check' : 'sparkles', size: 14 }),
          toast.message,
        ),
      ),
    ),
  )
}

// >>>>>>>>>>>>>>>>>>>>>>>>>>>> 45-editor.js >>>>>>>>>>>>>>>>>>>>>>>>>>>>
// Document editor: title, status, tags, formatting toolbar, split panes and preview.

const EDITOR_MODES = [
  { id: 'write', label: 'Write', icon: 'edit' },
  { id: 'split', label: 'Split', icon: 'columns' },
  { id: 'preview', label: 'Preview', icon: 'eye' },
]

/**
 * Replace the whole textarea value through the browser edit command so the native undo stack
 * survives a toolbar click. Returns false when the command is unavailable or did not take.
 */
function insertIntoTextarea(textarea, result) {
  if (!textarea || result === undefined || result === null) return false
  if (typeof document === 'undefined' || document === null || typeof document.execCommand !== 'function') return false
  try {
    const previous = textarea.value
    const previousStart = textarea.selectionStart
    const previousEnd = textarea.selectionEnd
    textarea.focus()
    textarea.setSelectionRange(0, previous.length)
    const replaced = document.execCommand('insertText', false, result.value)
    if (replaced !== true || textarea.value !== result.value) {
      textarea.value = previous
      textarea.setSelectionRange(previousStart, previousEnd)
      return false
    }
    return true
  } catch (error) {
    return false
  }
}

/** Wrap the current selection (or insert a placeholder) and keep the caret sensible. */
function applyWrap(textarea, before, after, placeholder) {
  if (!textarea) return null
  const start = textarea.selectionStart
  const end = textarea.selectionEnd
  const value = textarea.value
  const selected = value.slice(start, end) || placeholder || ''
  const next = value.slice(0, start) + before + selected + after + value.slice(end)
  const caret = start + before.length + selected.length
  return { value: next, selectionStart: start + before.length, selectionEnd: caret }
}

/** Prefix every line touched by the selection; a second click on the same style removes it. */
function applyLinePrefix(textarea, prefix, ordered) {
  if (!textarea) return null
  const value = textarea.value
  const start = textarea.selectionStart
  const end = textarea.selectionEnd
  const lineStart = value.lastIndexOf('\n', start - 1) + 1
  const lineEnd = value.indexOf('\n', end)
  const stop = lineEnd < 0 ? value.length : lineEnd
  const block = value.slice(lineStart, stop)
  const lines = block.split('\n')
  const task = /[-*+]\s+\[[ xX]\]\s/.test(prefix)
  const quote = /^\s*>\s*$/.test(prefix) || prefix.trim() === '>'
  const MARKER = /^(\s*)(?:>\s*|[-*+]\s+\[[ xX]\]\s+|[-*+]\s+|\d+[.)]\s+)?/
  const isOrdered = (line) => /^\s*\d+[.)]\s+/.test(line)
  const isTask = (line) => /^\s*[-*+]\s+\[[ xX]\]\s+/.test(line)
  const isBullet = (line) => /^\s*[-*+]\s+/.test(line)
  const isQuoted = (line) => /^\s*>\s+/.test(line)
  const styled = (line) => (task ? isTask(line) : ordered ? isOrdered(line) : quote ? isQuoted(line) : isBullet(line))
  const strip = (line) => line.replace(MARKER, '$1')
  const already = lines.every((line) => line.trim() === '' || styled(line))
  const nextBlock = lines
    .map((line, index) => {
      if (line.trim() === '') return line
      const indent = (/^\s*/.exec(line) || [''])[0]
      const body = strip(line).slice(indent.length)
      if (task) return isTask(line) ? line : indent + '- [ ] ' + body
      if (already) return indent + body
      const bullet = ordered ? String(index + 1) + '. ' : prefix
      return indent + bullet + body
    })
    .join('\n')
  return { value: value.slice(0, lineStart) + nextBlock + value.slice(stop), selectionStart: lineStart, selectionEnd: lineStart + nextBlock.length }
}
function TagEditor({ node, onAdd, onRemove }) {
  const [draft, setDraft] = React.useState('')
  const tags = Array.isArray(node.tags) ? node.tags : []
  const commit = () => {
    const value = draft.trim().replace(/^#/, '')
    setDraft('')
    if (value !== '') onAdd(value)
  }
  return h(
    'div',
    { className: 'dsh-scr-chip-wrap', style: { alignItems: 'center' } },
    tags.map((tag) => {
      const hue = model.tagHue(tag)
      return h(
        'span',
        {
          key: tag,
          className: 'dsh-scr-chip',
          style: { background: `hsla(${hue}, 65%, 55%, 0.16)`, color: `hsl(${hue}, 62%, 62%)` },
        },
        '#' + tag,
        h(
          'button',
          {
            type: 'button',
            className: 'dsh-scr-chip-x',
            title: 'Remove tag',
            onClick: () => onRemove(tag),
          },
          '×',
        ),
      )
    }),
    h('input', {
      className: 'dsh-scr-input',
      style: { width: 108, padding: '2px 8px', fontSize: 11.5, borderRadius: 999 },
      placeholder: '+ tag',
      value: draft,
      onChange: (event) => setDraft(event.target.value),
      onBlur: commit,
      onKeyDown: (event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
        }
      },
    }),
  )
}

function EditorToolbar({ textareaRef, onApply, onSave }) {
  const run = (builder) => {
    const textarea = textareaRef.current
    if (!textarea) return
    const result = builder(textarea)
    if (result) onApply(result)
  }
  const insert = (text, selectOffset) => () =>
    run((textarea) => {
      const start = textarea.selectionStart
      const value = textarea.value
      return {
        value: value.slice(0, start) + text + value.slice(textarea.selectionEnd),
        selectionStart: start + (selectOffset === undefined ? text.length : selectOffset),
        selectionEnd: start + (selectOffset === undefined ? text.length : selectOffset),
      }
    })

  const button = (icon, label, action) => h(IconButton, { icon, label, onClick: action, className: 'dsh-scr-tool-btn' })
  const sep = () => h('span', { key: 'sep' + Math.random(), className: 'dsh-scr-toolbar-sep' })

  return h(
    'div',
    { className: 'dsh-scr-toolbar' },
    h(
      'div',
      { className: 'dsh-scr-toolbar-group' },
      button('heading', 'Heading', insert('## ')),
      button('bold', 'Bold (Ctrl+B)', () => run((el) => applyWrap(el, '**', '**', 'bold text'))),
      button('italic', 'Italic (Ctrl+I)', () => run((el) => applyWrap(el, '*', '*', 'italic text'))),
      button('strike', 'Strikethrough', () => run((el) => applyWrap(el, '~~', '~~', 'text'))),
      button('code', 'Inline code', () => run((el) => applyWrap(el, '`', '`', 'code'))),
      button('code', 'Code block', insert('\n```js\nconst answer = 42\n```\n')),
    ),
    sep(),
    h(
      'div',
      { className: 'dsh-scr-toolbar-group' },
      button('listUl', 'Bullet list', () => run((el) => applyLinePrefix(el, '- ', false))),
      button('listOl', 'Numbered list', () => run((el) => applyLinePrefix(el, '1. ', true))),
      button('check', 'Task list', () => run((el) => applyLinePrefix(el, '- [ ] ', false))),
      button('quote', 'Quote', () => run((el) => applyLinePrefix(el, '> ', false))),
    ),
    sep(),
    h(
      'div',
      { className: 'dsh-scr-toolbar-group' },
      button('link', 'Link', insert('[label](https://)', 7)),
      button('image', 'Image', insert('![alt](https://)', 6)),
      button('table', 'Table', insert('\n| Column | Column |\n| --- | --- |\n| Cell | Cell |\n')),
      button('hr', 'Divider', insert('\n\n---\n\n')),
      button('sparkles', 'Callout', insert('\n::: note\nA short note.\n:::\n')),
    ),
    h('span', { className: 'dsh-scr-spacer' }),
    h(IconButton, { icon: 'save', label: 'Save now (Ctrl+S)', onClick: onSave, className: 'dsh-scr-tool-btn' }),
  )
}

function DocumentEditor({ store, snapshot, node, ui, actions }) {
  const settings = snapshot.settings || {}
  const mode = settings.editorMode || 'split'
  const [title, setTitle] = React.useState(node.title)
  const [content, setContent] = React.useState(node.content || '')
  const textareaRef = React.useRef(null)
  const previewRef = React.useRef(null)
  const pendingRef = React.useRef(null)
  const currentIdRef = React.useRef(node.id)

  const flush = React.useRef(() => {})
  flush.current = () => {
    const pending = pendingRef.current
    pendingRef.current = null
    if (pending === null) return
    actions.setContent(pending.nodeId, pending.content)
  }

  const scheduleFlush = React.useMemo(
    () =>
      debounce(() => {
        flush.current()
      }, 420),
    [],
  )

  React.useEffect(() => {
    return () => {
      scheduleFlush.cancel()
      flush.current()
    }
  }, [node.id])

  const resetTokenRef = React.useRef(store.state.resetToken || 0)

  React.useEffect(() => {
    const token = store.state.resetToken || 0
    const tokenChanged = token !== resetTokenRef.current
    const nodeChanged = currentIdRef.current !== node.id
    if (!tokenChanged && !nodeChanged) return
    scheduleFlush.cancel()
    if (tokenChanged) {
      // The store took the host copy; the keystrokes it had not flushed are what Reload drops.
      pendingRef.current = null
    } else {
      flush.current()
    }
    resetTokenRef.current = token
    currentIdRef.current = node.id
    setTitle(node.title)
    setContent(node.content || '')
  }, [node.id, node.title, node.content, store.state.resetToken])

  const stageContent = (value) => {
    setContent(value)
    pendingRef.current = { nodeId: node.id, content: value }
    scheduleFlush()
  }

  const applyResult = (result) => {
    const textarea = textareaRef.current
    if (textarea !== null && insertIntoTextarea(textarea, result)) {
      textarea.setSelectionRange(result.selectionStart, result.selectionEnd)
      return
    }
    stageContent(result.value)
    requestAnimationFrame(() => {
      const target = textareaRef.current
      if (target === null) return
      target.focus()
      target.setSelectionRange(result.selectionStart, result.selectionEnd)
    })
  }

  const toggleTask = (lineIndex, checked) => {
    stageContent(toggleTaskLine(content, lineIndex, checked))
  }

  const onTextareaKeyDown = (event) => {
    if ((event.ctrlKey || event.metaKey) && !event.altKey) {
      const key = event.key.toLowerCase()
      const textarea = event.currentTarget
      if (key === 'b') {
        event.preventDefault()
        applyResult(applyWrap(textarea, '**', '**', 'bold text'))
      } else if (key === 'i') {
        event.preventDefault()
        applyResult(applyWrap(textarea, '*', '*', 'italic text'))
      } else if (key === 's') {
        event.preventDefault()
        flush.current()
        actions.saveNow()
      }
      return
    }
    if (event.key === 'Tab') {
      event.preventDefault()
      const textarea = event.currentTarget
      const start = textarea.selectionStart
      const value = textarea.value
      applyResult({ value: value.slice(0, start) + '  ' + value.slice(textarea.selectionEnd), selectionStart: start + 2, selectionEnd: start + 2 })
    }
  }

  const syncScroll = (event) => {
    if (mode !== 'split' || previewRef.current === null) return
    const source = event.currentTarget
    const ratio = source.scrollTop / Math.max(1, source.scrollHeight - source.clientHeight)
    const preview = previewRef.current
    preview.scrollTop = ratio * Math.max(0, preview.scrollHeight - preview.clientHeight)
  }

  const stats = markdownStats(content)
  const trail = model.nodeTrail(snapshot, node.id).slice(0, -1)

  return h(
    'div',
    { className: 'dsh-scr-editor dsh-scr-view' },
    h(
      'div',
      { className: 'dsh-scr-doc-head' },
      h('input', {
        className: 'dsh-scr-doc-title',
        value: title,
        'aria-label': 'Document title',
        onChange: (event) => setTitle(event.target.value),
        onBlur: () => {
          const next = title.trim()
          if (next !== '' && next !== node.title) actions.renameNode(node.id, next)
          else setTitle(node.title)
        },
        onKeyDown: (event) => {
          if (event.key === 'Enter') {
            event.preventDefault()
            event.currentTarget.blur()
            textareaRef.current && textareaRef.current.focus()
          }
        },
      }),
      h(
        'div',
        { className: 'dsh-scr-doc-meta' },
        trail.length > 0
          ? h(
              'span',
              { style: { display: 'inline-flex', alignItems: 'center', gap: 4 } },
              trail.map((parent, index) =>
                h('span', { key: parent.id, style: { display: 'inline-flex', alignItems: 'center', gap: 4 } },
                  index > 0 ? h('span', { className: 'dsh-scr-doc-meta-sep' }, '/') : null,
                  h(Icon, { name: parent.icon || 'folder', size: 12 }),
                  parent.title,
                ),
              ),
              h('span', { className: 'dsh-scr-doc-meta-sep' }, '/'),
            )
          : null,
        h(
          'button',
          {
            type: 'button',
            className: 'dsh-scr-status-pill',
            title: 'Cycle status',
            style: { color: model.statusTokenOf(node.status) },
            onClick: () => {
              const order = model.STATUS_ORDER
              const index = order.indexOf(node.status)
              actions.setStatus(node.id, order[(index + 1) % order.length])
            },
          },
          h('span', { className: 'dsh-scr-status-dot' }),
          model.statusLabelOf(node.status),
        ),
        h('span', { className: 'dsh-scr-doc-meta-sep' }, '·'),
        h('span', null, 'Edited ' + model.relativeTime(node.updatedAt)),
        h('span', { className: 'dsh-scr-doc-meta-sep' }, '·'),
        h('span', null, stats.words + ' words'),
        h('span', { className: 'dsh-scr-doc-meta-sep' }, '·'),
        h('span', null, stats.minutes + ' min read'),
        h('span', { className: 'dsh-scr-spacer', style: { flex: '1 1 auto' } }),
        h('span', { className: 'dsh-scr-seg' },
          EDITOR_MODES.map((entry) =>
            h(
              'button',
              {
                key: entry.id,
                type: 'button',
                className: cx('dsh-scr-seg-btn', mode === entry.id && 'is-active'),
                onClick: () => actions.patchSettings({ editorMode: entry.id }),
              },
              h(Icon, { name: entry.icon, size: 12 }),
              entry.label,
            ),
          ),
        ),
        h(IconButton, {
          icon: 'star',
          label: node.favorite ? 'Remove from favourites' : 'Add to favourites',
          active: node.favorite === true,
          onClick: () => actions.toggleFavorite(node.id),
        }),
        h(IconButton, { icon: 'download', label: 'Download as Markdown', onClick: () => actions.exportDocument(node.id) }),
        h(IconButton, { icon: 'trash', label: 'Move to trash', danger: true, onClick: () => actions.trashNode(node.id) }),
      ),
      h(
        'div',
        { className: 'dsh-scr-doc-meta' },
        h(TagEditor, {
          node,
          onAdd: (tag) => actions.addTag(node.id, tag),
          onRemove: (tag) => actions.removeTag(node.id, tag),
        }),
        h('span', { className: 'dsh-scr-spacer', style: { flex: '1 1 auto' } }),
        h(
          'span',
          { className: 'dsh-scr-save-state' },
          h('span', {
            className: cx(
              'dsh-scr-save-dot',
              store.state.saveState === 'saving' && 'is-saving',
              store.state.saveState === 'saved' && 'is-saved',
              store.state.saveState === 'error' && 'is-error',
              store.state.saveState === 'conflict' && 'is-error',
            ),
          }),
          store.state.saveState === 'conflict'
            ? 'Unsaved - resolve conflict'
            : store.state.saveState === 'saving'
              ? 'Saving…'
              : store.state.saveState === 'error'
                ? 'Save failed'
                : 'Saved ' + model.relativeTime(store.state.updatedAt),
        ),
      ),
    ),
    h(EditorToolbar, {
      textareaRef,
      onApply: applyResult,
      onSave: () => {
        flush.current()
        actions.saveNow()
      },
    }),
    h(
      'div',
      { className: 'dsh-scr-panes' },
      mode !== 'preview'
        ? h(
            'div',
            { className: cx('dsh-scr-pane', mode === 'split' ? 'is-edit' : 'is-full') },
            mode === 'split' ? h('div', { className: 'dsh-scr-pane-label' }, 'Markdown') : null,
            h('textarea', {
              ref: textareaRef,
              className: 'dsh-scr-textarea',
              value: content,
              spellCheck: true,
              placeholder: 'Start writing in Markdown…',
              style: { fontSize: (settings.fontSize || 15) + 'px' },
              onChange: (event) => stageContent(event.target.value),
              onKeyDown: onTextareaKeyDown,
              onScroll: syncScroll,
              onBlur: () => flush.current(),
            }),
          )
        : null,
      mode !== 'write'
        ? h(
            'div',
            { className: cx('dsh-scr-pane', mode === 'split' ? 'is-full' : 'is-full') },
            mode === 'split' ? h('div', { className: 'dsh-scr-pane-label' }, 'Preview') : null,
            h(
              'div',
              { ref: previewRef, className: 'dsh-scr-preview', style: { '--scr-md-size': (settings.fontSize || 15) + 'px' } },
              h('div', { className: 'dsh-scr-md' }, renderMarkdown(content, { onToggleTask: toggleTask })),
            ),
          )
        : null,
    ),
    h(
      'section',
      { className: 'dsh-scr-editor-media' },
      h(
        'div',
        { className: 'dsh-scr-editor-mediahead' },
        h('span', { className: 'dsh-scr-editor-mediatitle' }, 'Attachments'),
        h('span', { className: 'dsh-scr-attach-count' }, model.mediaOf(node).length + ' file(s)'),
        actions.busy === 'media' ? h('span', { className: 'dsh-scr-attach-busy' }, 'Uploading…') : null,
      ),
      h(MediaGrid, {
        items: model.mediaOf(node),
        emptyHint: 'Attach an image, PDF, audio or video file — previews open right inside the editor.',
        onUpload: (files) => actions.uploadMedia(node.id, files),
        onPreview: (media) => actions.openPreview(media),
        onRemove: (media) => actions.removeMedia(node.id, media.id),
      }),
    ),
  )
}

// >>>>>>>>>>>>>>>>>>>>>>>>>>>> 50-search.js >>>>>>>>>>>>>>>>>>>>>>>>>>>>
// Search: ranking over the snapshot, the full search overlay, and the Ctrl+K command palette.
// Concatenated into the bundle factory scope (no imports/exports/JSX); `h`, `React`, `cx`,
// `model` helpers and `CSS_CHUNKS` come from the sibling files above this one.

const AXL_SEARCH_LIMIT = 50
const AXL_SEARCH_RECENT = 8
const AXL_SEARCH_EXCERPT_RADIUS = 120

/** Markdown-stripped plain text when the sibling helper exists, raw content otherwise. */
function scrSearchPlainText(value) {
  const text = String(value === undefined || value === null ? '' : value)
  if (typeof markdownPlainText === 'function') {
    try {
      const plain = markdownPlainText(text)
      if (typeof plain === 'string') return plain
    } catch (error) {
      console.warn('[dsh-scriptorium] markdownPlainText failed, falling back to raw content', error)
    }
  }
  return text
}

/** Sort key: numeric updatedAt, invalid/missing dates sort last. */
function scrSearchStampOf(node) {
  const parsed = Date.parse(String((node && node.updatedAt) || ''))
  return Number.isNaN(parsed) ? 0 : parsed
}

/** Content weight: bounded so body hits can never outrank a title hit. */
function scrSearchContentWeight(body, needle) {
  const haystack = String(body === undefined || body === null ? '' : body).toLowerCase()
  const lowerNeedle = String(needle || '').toLowerCase()
  if (haystack === '' || lowerNeedle === '') return 0
  const first = haystack.indexOf(lowerNeedle)
  if (first < 0) return 0
  let hits = 0
  let cursor = 0
  while (hits < 12) {
    const found = haystack.indexOf(lowerNeedle, cursor)
    if (found < 0) break
    hits += 1
    cursor = found + lowerNeedle.length
  }
  return 40 + Math.min(60, hits * 12) - Math.min(20, Math.floor(first / 40))
}

/** Highlight segments -> spans; hit spans carry the shared highlight class. */
function scrSearchSegments(segments) {
  const list = Array.isArray(segments) ? segments : []
  return list.map((segment, index) =>
    segment.hit === true
      ? h('span', { key: 'hit-' + index, className: 'dsh-scr-search-hit' }, segment.text)
      : h('span', { key: 'plain-' + index }, segment.text),
  )
}

/** Search every live document; blank query means "most recently updated". */
function searchDocuments(snapshot, query, options) {
  const opts = options || {}
  const source = snapshot && Array.isArray(snapshot.nodes) ? snapshot.nodes : []
  const needle = String(query === undefined || query === null ? '' : query).trim()
  const includeTrashed = opts.includeTrashed === true
  const workspaceId = opts.workspaceId === undefined || opts.workspaceId === null ? null : String(opts.workspaceId)
  const requested = Number(opts.limit)
  const limit = Number.isFinite(requested) && requested > 0 ? Math.floor(requested) : AXL_SEARCH_LIMIT

  const pool = source.filter((node) => {
    if (node === null || typeof node !== 'object') return false
    if (node.kind === 'folder') return false
    if (includeTrashed !== true && node.trashed === true) return false
    if (workspaceId !== null && String(node.workspaceId) !== workspaceId) return false
    return true
  })

  if (needle === '') {
    const recent = pool
      .slice()
      .sort((left, right) => scrSearchStampOf(right) - scrSearchStampOf(left))
      .slice(0, Math.min(AXL_SEARCH_RECENT, limit))
    return recent.map((node) => ({
      node,
      score: 0,
      titleSegments: matchSegments(node.title, ''),
      excerptSegments: matchSegments(excerptFor(scrSearchPlainText(node.content), '', AXL_SEARCH_EXCERPT_RADIUS), ''),
    }))
  }

  const scored = []
  for (const node of pool) {
    const titleScore = fuzzyScore(needle, node.title)
    let tagScore = null
    if (Array.isArray(node.tags)) {
      for (const tag of node.tags) {
        const value = fuzzyScore(needle, tag)
        if (value !== null && (tagScore === null || value > tagScore)) tagScore = value
      }
    }
    const body = scrSearchPlainText(node.content)
    const contentScore = scrSearchContentWeight(body, needle)
    if (titleScore === null && tagScore === null && contentScore === 0) continue
    scored.push({
      node,
      score: (titleScore || 0) * 3 + (tagScore || 0) * 2 + contentScore,
      titleSegments: matchSegments(node.title, needle),
      excerptSegments: matchSegments(excerptFor(body, needle, AXL_SEARCH_EXCERPT_RADIUS), needle),
    })
  }

  scored.sort(
    (left, right) => right.score - left.score || scrSearchStampOf(right.node) - scrSearchStampOf(left.node),
  )
  return scored.slice(0, limit)
}

/** Wrap-around cursor movement shared by both lists. */
function scrSearchStep(index, delta, length) {
  if (length <= 0) return 0
  const base = Math.min(Math.max(index, 0), length - 1)
  return ((base + delta) % length + length) % length
}

function SearchOverlay(props) {
  const input = props || {}
  const snapshot = input.snapshot
  const query = input.query === undefined || input.query === null ? '' : String(input.query)
  const workspaceId = input.workspaceId === undefined ? undefined : input.workspaceId
  const onQueryChange = typeof input.onQueryChange === 'function' ? input.onQueryChange : () => {}
  const onPick = typeof input.onPick === 'function' ? input.onPick : () => {}
  const onClose = typeof input.onClose === 'function' ? input.onClose : () => {}

  const fieldRef = React.useRef(null)
  const listRef = React.useRef(null)
  const selectedState = React.useState(0)
  const selected = selectedState[0]
  const setSelected = selectedState[1]

  const trimmed = query.trim()
  const hasQuery = trimmed !== ''

  const results = React.useMemo(
    () => searchDocuments(snapshot, trimmed, { workspaceId }),
    [snapshot, trimmed, workspaceId],
  )

  const count = results.length
  const activeIndex = count === 0 ? -1 : Math.min(selected, count - 1)

  React.useEffect(() => {
    const field = fieldRef.current
    if (field === null || field === undefined) return
    field.focus()
  }, [])

  React.useEffect(() => {
    setSelected(0)
  }, [trimmed, workspaceId])

  React.useEffect(() => {
    const list = listRef.current
    if (list === null || list === undefined) return
    const row = list.querySelector('[data-index="' + activeIndex + '"]')
    if (row === null || row === undefined) return
    if (typeof row.scrollIntoView === 'function') row.scrollIntoView({ block: 'nearest' })
  }, [activeIndex, count])

  const pickAt = (index) => {
    const result = results[index]
    if (result === undefined) return
    onPick(result.node, result)
  }

  const onKeyDown = (event) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setSelected(scrSearchStep(activeIndex, 1, count))
      return
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      setSelected(scrSearchStep(activeIndex, -1, count))
      return
    }
    if (event.key === 'Enter') {
      event.preventDefault()
      if (activeIndex >= 0) pickAt(activeIndex)
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation()
      onClose()
    }
  }

  const renderRow = (result, index) => {
    const node = result.node
    const workspace = workspaceById(snapshot, node.workspaceId)
    const tags = Array.isArray(node.tags) ? node.tags.slice(0, 4) : []
    const excerptText = result.excerptSegments
      .map((segment) => segment.text)
      .join('')
      .trim()
    return h(
      'div',
      {
        key: node.id,
        id: 'dsh-scr-search-row-' + index,
        className: 'dsh-scr-search-row',
        role: 'option',
        'aria-selected': index === activeIndex ? 'true' : 'false',
        'data-index': index,
        'data-selected': index === activeIndex ? 'true' : 'false',
        style: { animationDelay: Math.min(index, 12) * 12 + 'ms' },
        onMouseDown: (event) => event.preventDefault(),
        onMouseEnter: () => setSelected(index),
        onClick: () => pickAt(index),
      },
      h(
        'div',
        { className: 'dsh-scr-search-rowtop' },
        h('span', { className: 'dsh-scr-search-rowtitle' }, scrSearchSegments(result.titleSegments)),
        h('span', { className: 'dsh-scr-search-rowtime' }, relativeTime(node.updatedAt)),
      ),
      h(
        'div',
        { className: 'dsh-scr-search-rowmeta' },
        tags.map((tag) =>
          h('span', { key: 'tag:' + tag, className: 'dsh-scr-search-tag' }, '#' + tag),
        ),
        h(
          'span',
          { className: 'dsh-scr-search-ws' },
          workspace === null || workspace === undefined ? 'Unknown workspace' : workspace.name,
        ),
      ),
      excerptText === ''
        ? h('div', { className: 'dsh-scr-search-excerpt dsh-scr-search-excerpt-empty' }, 'No content yet')
        : h('div', { className: 'dsh-scr-search-excerpt' }, scrSearchSegments(result.excerptSegments)),
    )
  }

  const renderEmpty = () =>
    h(
      'div',
      { className: 'dsh-scr-search-empty' },
      h('span', { className: 'dsh-scr-search-emptytitle' }, 'No documents match “' + trimmed + '”'),
      h(
        'span',
        { className: 'dsh-scr-search-emptysub' },
        'Try a shorter word, a tag name, or another workspace.',
      ),
      h(
        'button',
        {
          type: 'button',
          className: 'dsh-scr-search-clear',
          onMouseDown: (event) => event.preventDefault(),
          onClick: () => onQueryChange(''),
        },
        'Clear search',
      ),
    )

  return h(
    'div',
    {
      className: 'dsh-scr-search-panel',
      role: 'dialog',
      'aria-modal': 'true',
      'aria-label': 'Search documents',
      onKeyDown,
    },
    h(
      'div',
      { className: 'dsh-scr-search-head' },
      h('span', { className: 'dsh-scr-search-glyph', 'aria-hidden': 'true' }, '⌕'),
      h('input', {
        ref: fieldRef,
        className: 'dsh-scr-search-input',
        type: 'text',
        value: query,
        placeholder: 'Search titles, tags and content…',
        autoComplete: 'off',
        spellCheck: false,
        'aria-label': 'Search query',
        onChange: (event) => onQueryChange(event.target.value),
      }),
      h(
        'span',
        { className: 'dsh-scr-search-count' },
        hasQuery
          ? count === 1
            ? '1 result'
            : count + ' results'
          : count === 1
            ? '1 recent'
            : count + ' recent',
      ),
      h(
        'button',
        { type: 'button', className: 'dsh-scr-search-close', onClick: onClose, 'aria-label': 'Close search' },
        'esc',
      ),
    ),
    hasQuery
      ? null
      : h(
          'div',
          { className: 'dsh-scr-search-hint' },
          h('span', { className: 'dsh-scr-search-hinttitle' }, 'Search across every workspace'),
          h(
            'span',
            { className: 'dsh-scr-search-hintsub' },
            'Matches titles, tags and body text — pass a workspace to narrow it down.',
          ),
        ),
    hasQuery
      ? null
      : count === 0
        ? null
        : h('div', { className: 'dsh-scr-search-section' }, 'Recent documents'),
    h(
      'div',
      {
        ref: listRef,
        className: 'dsh-scr-search-body',
        role: 'listbox',
        'aria-label': 'Search results',
        'aria-activedescendant': activeIndex >= 0 ? 'dsh-scr-search-row-' + activeIndex : undefined,
      },
      count === 0 ? (hasQuery ? renderEmpty() : h('div', { className: 'dsh-scr-search-empty' }, h('span', { className: 'dsh-scr-search-emptysub' }, 'No documents yet — create one to see it here.'))) : results.map(renderRow),
    ),
    h(
      'div',
      { className: 'dsh-scr-search-foot' },
      h('span', null, '↑↓ navigate · ↵ open · esc close'),
      h('span', { className: 'dsh-scr-search-footnote' }, hasQuery ? 'ranked by title, tags, content' : 'by last edit'),
    ),
  )
}

/** Filter + rank palette commands; matches title (×2) and hint (×1). */
const AXL_PALETTE_RECENT = []
const AXL_PALETTE_RECENT_MAX = 5

/** Remember a command id so the palette can float recently used entries to the top. */
function scrPaletteTouch(commandId) {
  if (commandId === undefined || commandId === null) return
  const id = String(commandId)
  if (id === '') return
  const at = AXL_PALETTE_RECENT.indexOf(id)
  if (at >= 0) AXL_PALETTE_RECENT.splice(at, 1)
  AXL_PALETTE_RECENT.unshift(id)
  if (AXL_PALETTE_RECENT.length > AXL_PALETTE_RECENT_MAX) AXL_PALETTE_RECENT.length = AXL_PALETTE_RECENT_MAX
}

function scrPaletteFilter(commands, query) {
  const needle = String(query === undefined || query === null ? '' : query).trim()
  const scored = []
  commands.forEach((command, order) => {
    if (command === null || typeof command !== 'object') return
    const title = String(command.title === undefined || command.title === null ? '' : command.title)
    const hint = String(command.hint === undefined || command.hint === null ? '' : command.hint)
    const recentRank = AXL_PALETTE_RECENT.indexOf(String(command.id === undefined || command.id === null ? '' : command.id))
    const recentBoost = recentRank < 0 ? 0 : (AXL_PALETTE_RECENT_MAX - recentRank) * 4
    if (needle === '') {
      scored.push({ command, score: recentBoost, order })
      return
    }
    const titleScore = fuzzyScore(needle, title)
    const hintScore = fuzzyScore(needle, hint)
    if (titleScore === null && hintScore === null) return
    scored.push({ command, score: (titleScore || 0) * 2 + (hintScore || 0) + recentBoost, order })
  })
  scored.sort((left, right) => right.score - left.score || left.order - right.order)
  return scored.map((entry) => entry.command)
}

/** Group in visual order and stamp each row with its keyboard index. */
function scrPaletteGroups(commands) {
  const names = []
  const buckets = new Map()
  for (const command of commands) {
    const raw = command.group === undefined || command.group === null ? '' : String(command.group).trim()
    const name = raw === '' ? 'Commands' : raw
    if (!buckets.has(name)) {
      buckets.set(name, [])
      names.push(name)
    }
    buckets.get(name).push(command)
  }
  const groups = []
  let cursor = 0
  for (const name of names) {
    const items = buckets.get(name).map((command) => {
      const entry = { command, index: cursor }
      cursor += 1
      return entry
    })
    groups.push({ name, items })
  }
  return groups
}

function scrPaletteIcon(icon) {
  if (icon === undefined || icon === null || icon === false) return null
  if (typeof icon === 'string') {
    const known = Object.prototype.hasOwnProperty.call(ICONS, icon)
    return h('span', { className: 'dsh-scr-palette-icon', 'aria-hidden': 'true' }, known ? h(Icon, { name: icon, size: 15 }) : icon)
  }
  if (typeof icon === 'function') {
    return h('span', { className: 'dsh-scr-palette-icon', 'aria-hidden': 'true' }, h(icon, { size: 15 }))
  }
  return h('span', { className: 'dsh-scr-palette-icon', 'aria-hidden': 'true' }, icon)
}

function CommandPalette(props) {
  const input = props || {}
  const commands = Array.isArray(input.commands) ? input.commands : []
  const onClose = typeof input.onClose === 'function' ? input.onClose : () => {}

  const fieldRef = React.useRef(null)
  const listRef = React.useRef(null)
  const queryState = React.useState('')
  const query = queryState[0]
  const setQuery = queryState[1]
  const selectedState = React.useState(0)
  const selected = selectedState[0]
  const setSelected = selectedState[1]

  const filtered = React.useMemo(() => scrPaletteFilter(commands, query), [commands, query])
  const groups = React.useMemo(() => scrPaletteGroups(filtered), [filtered])
  const count = filtered.length
  const activeIndex = count === 0 ? -1 : Math.min(selected, count - 1)
  const trimmed = query.trim()

  React.useEffect(() => {
    const field = fieldRef.current
    if (field === null || field === undefined) return
    field.focus()
  }, [])

  React.useEffect(() => {
    setSelected(0)
  }, [trimmed])

  React.useEffect(() => {
    const list = listRef.current
    if (list === null || list === undefined) return
    const row = list.querySelector('[data-index="' + activeIndex + '"]')
    if (row === null || row === undefined) return
    if (typeof row.scrollIntoView === 'function') row.scrollIntoView({ block: 'nearest' })
  }, [activeIndex, count])

  const runAt = (index) => {
    const command = filtered[index]
    if (command === undefined) return
    scrPaletteTouch(command.id)
    try {
      if (typeof command.run === 'function') command.run()
    } catch (error) {
      console.error('[dsh-scriptorium] command failed', error)
    } finally {
      onClose()
    }
  }

  const onKeyDown = (event) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setSelected(scrSearchStep(activeIndex, 1, count))
      return
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      setSelected(scrSearchStep(activeIndex, -1, count))
      return
    }
    if (event.key === 'Enter') {
      event.preventDefault()
      if (activeIndex >= 0) runAt(activeIndex)
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      event.stopPropagation()
      onClose()
    }
  }

  return h(
    'div',
    {
      className: 'dsh-scr-palette-backdrop',
      onMouseDown: (event) => {
        if (event.target === event.currentTarget) onClose()
      },
    },
    h(
      'div',
      {
        className: 'dsh-scr-palette-card',
        role: 'dialog',
        'aria-modal': 'true',
        'aria-label': 'Command palette',
        onKeyDown,
        onMouseDown: (event) => event.stopPropagation(),
      },
      h(
        'div',
        { className: 'dsh-scr-palette-head' },
        h('span', { className: 'dsh-scr-palette-glyph', 'aria-hidden': 'true' }, '⌘'),
        h('input', {
          ref: fieldRef,
          className: 'dsh-scr-palette-input',
          type: 'text',
          value: query,
          placeholder: 'Type a command…',
          autoComplete: 'off',
          spellCheck: false,
          'aria-label': 'Command query',
          onChange: (event) => setQuery(event.target.value),
        }),
        h('span', { className: 'dsh-scr-palette-count' }, count === 1 ? '1' : String(count)),
      ),
      h(
        'div',
        {
          ref: listRef,
          className: 'dsh-scr-palette-list',
          role: 'listbox',
          'aria-label': 'Commands',
          'aria-activedescendant': activeIndex >= 0 ? 'dsh-scr-palette-row-' + activeIndex : undefined,
        },
        count === 0
          ? h(
              'div',
              { className: 'dsh-scr-palette-empty' },
              h('span', { className: 'dsh-scr-palette-emptytitle' }, 'No matching command'),
              trimmed === ''
                ? null
                : h('span', { className: 'dsh-scr-palette-emptysub' }, 'Nothing answers “' + trimmed + '”.'),
            )
          : groups.map((group) =>
              h(
                'div',
                { key: 'group:' + group.name, className: 'dsh-scr-palette-group', role: 'presentation' },
                h('div', { className: 'dsh-scr-palette-grouplabel' }, group.name),
                group.items.map((entry) => {
                  const command = entry.command
                  const isActive = entry.index === activeIndex
                  return h(
                    'div',
                    {
                      key: String(command.id === undefined ? group.name + ':' + entry.index : command.id),
                      id: 'dsh-scr-palette-row-' + entry.index,
                      className: 'dsh-scr-palette-row',
                      role: 'option',
                      'aria-selected': isActive ? 'true' : 'false',
                      'data-index': entry.index,
                      'data-selected': isActive ? 'true' : 'false',
                      onMouseDown: (event) => event.preventDefault(),
                      onMouseEnter: () => setSelected(entry.index),
                      onClick: () => runAt(entry.index),
                    },
                    scrPaletteIcon(command.icon),
                    h(
                      'span',
                      { className: 'dsh-scr-palette-rowmain' },
                      h(
                        'span',
                        { className: 'dsh-scr-palette-title' },
                        scrSearchSegments(matchSegments(command.title, trimmed)),
                      ),
                      command.hint === undefined || command.hint === null || String(command.hint) === ''
                        ? null
                        : h('span', { className: 'dsh-scr-palette-hint' }, String(command.hint)),
                    ),
                  )
                }),
              ),
            ),
      ),
      h(
        'div',
        { className: 'dsh-scr-palette-foot' },
        h('span', null, '↑↓ navigate · ↵ run · esc close'),
      ),
    ),
  )
}

